from pathlib import Path
import json,base64
R=Path(__file__).resolve().parents[2];O=R/'renders/cafe_multietage_v2';m=json.loads((O/'manifest.json').read_text())
def uri(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
data={}
for entry in m['levels']:
 p=O/entry['path'];data[entry['id']]={**entry,'images':{n:uri(p/(n+'.png')) for n in entry['layers']},'views':{mode:uri(p/f'02_vues_exterieures_{mode}.png') for mode in ['jour','nuit']},'schema':uri(p/'schema.png')}
h='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Café · cinq niveaux et fenêtres circulaires</title><style>*{box-sizing:border-box}body{margin:0;background:#201a18;color:#f4e9d3;font:16px system-ui}header,main,footer{max-width:1250px;margin:auto;padding:24px}h1{font-size:28px;margin:8px 0}p{color:#d0bea6;line-height:1.6}.tag{color:#edc379;font-size:12px;letter-spacing:2px}.bar{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:22px}select,button{padding:11px;background:#533e2b;border:1px solid #9e7952;border-radius:6px;color:white}.view{display:grid;grid-template-columns:minmax(0,1fr) 250px;gap:22px}canvas{width:100%;image-rendering:pixelated;background:repeating-conic-gradient(#352a23 0% 25%,#30261f 0% 50%) 50%/16px 16px}aside{padding:16px;background:#382b22;border-radius:8px}label{display:block;margin:15px 0;font-size:14px}a{color:#f5d59b}small{color:#d5c4aa}footer{border-top:1px solid #796047}@media(max-width:780px){.view{grid-template-columns:1fr}}</style><header><div class="tag">HALCYON × SPINDA CAFÉ / PIÈCES VIDES</div><h1>Deux sous-sols, un accueil, deux étages</h1><p>Layouts d’origine légèrement agrandis. Accès canoniques conservés avec leurs ombres et lumières, sans escalier ajouté au milieu. Fenêtres circulaires : petits hublots espacés au deuxième étage, aucune baie vitrée. Pas de tables, chaises, comptoirs ou personnages.</p></header><main><div class="bar"><select id="variant"><option value="A">Plan A</option><option value="B">Plan B · agrandissement léger +</option></select><select id="level"><option value="etage2" selected>Étage +2 · petits hublots</option><option value="etage1">Étage +1</option><option value="accueil">Salle d’accueil</option><option value="ss1">Sous-sol −1</option><option value="ss2">Sous-sol −2</option></select><select id="mode"><option value="jour">Vue extérieure · jour</option><option value="nuit">Vue extérieure · nuit</option></select><button id="schema">Voir schéma de circulation</button><button id="export">Exporter PNG</button></div><div class="view"><section><canvas id="view"></canvas><p id="status"></p><p id="connections"></p></section><aside><b>Calques</b><div id="layers"></div><small>↓ télécharge chaque PNG aligné. Le seuil original est copié sans étirement, ombres et lumière comprises. Aucun nouvel escalier de liaison.</small></aside></div></main><footer><p>Matériaux : Halcyon / Palikadude et ExplorersOfSkyOrigins / Minemaker0430. Les dimensions augmentent légèrement ; la forme de la salle et son seuil original sont conservés. Le plancher, les panneaux et la bordure rocheuse ne proviennent pas d’une génération de matière.</p><small>Les ornements muraux fixes du café sont conservés. Les sous-sols n’ont pas de fenêtres extérieures. Le choix jour/nuit ne modifie que le paysage visible à travers les hublots, pas l’éclairage intérieur. Pas de validation PMDO.</small></footer><script>const DATA=__DATA__;function im(s){const i=new Image();i.src=s;return i}let variant='A',level='etage2',mode='jour',schema=false,active,images={},visible={};const names={ '00_fond_canonique':'Fond canonique','01_sol_vide':'Plancher vide','02_vues':'Vues extérieures','03_bois_murs':'Murs et panneaux bois','04_bordure_rocheuse':'Bordure rocheuse','05_cadres_fenetres':'Cadres circulaires','06_escaliers':'Accès original et éclairage'},order=Object.keys(names),c=document.getElementById('view'),ctx=c.getContext('2d');function save(s,n){const a=document.createElement('a');a.href=s;a.download=n;a.click()}function source(k){return k==='02_vues'?active.views[mode]:active.images[k]}function setup(){active=DATA[variant+'_'+level];[c.width,c.height]=active.size;images={};visible={};const root=document.getElementById('layers');root.innerHTML='';for(const k of order){images[k]=im(source(k));visible[k]=true;const l=document.createElement('label'),ch=document.createElement('input'),a=document.createElement('a');ch.type='checkbox';ch.checked=true;ch.onchange=()=>visible[k]=ch.checked;a.href=source(k);a.download=active.id+'_'+k+'.png';a.textContent=' ↓';l.append(ch,document.createTextNode(' '+names[k]),a);root.append(l)}images.schema=im(active.schema);document.getElementById('status').textContent=active.title+' · '+variant+' · '+active.size.join(' × ')+' · '+(active.window_boxes.length?active.window_boxes.length+' fenêtres rondes, diamètre extérieur '+active.window_diameter+' px':'sans fenêtre extérieure');document.getElementById('connections').textContent='Accès conservé : '+active.connections.map(p=>p.direction+' → '+p.target).join(' ; ')}document.getElementById('variant').onchange=e=>{variant=e.target.value;setup()};document.getElementById('level').onchange=e=>{level=e.target.value;setup()};document.getElementById('mode').onchange=e=>{mode=e.target.value;setup()};document.getElementById('schema').onclick=e=>{schema=!schema;e.target.textContent=schema?'Voir rendu texturé':'Voir schéma de circulation'};document.getElementById('export').onclick=()=>save(c.toDataURL(),active.id+'_'+mode+'.png');function draw(i){if(i.complete&&i.naturalWidth)ctx.drawImage(i,0,0)}function render(){ctx.clearRect(0,0,c.width,c.height);if(schema)draw(images.schema);else for(const k of order)if(visible[k])draw(images[k]);requestAnimationFrame(render)}setup();requestAnimationFrame(render);</script></html>'''
(R/'apercu_cafe_multietage_v2.html').write_text(h.replace('__DATA__',json.dumps(data)),encoding='utf8')
